import unittest; import random; from copies import sorted_copy

class TestSortedCopy(unittest.TestCase):
    def test_fuzz_random_integers(self):
        rng = random.Random(1234)
        for _ in range(500):
            xs = [rng.randint(-100, 100) for _ in range(rng.randint(0, 100))]
            self.assertEqual(sorted_copy(xs), sorted(xs))

if __name__ == '__main__':
    unittest.main()

